function statusClass(s){s=String(s||'').toLowerCase();return s.includes('verified')||s==='selected'||s==='complete'||s==='completed'?'success':s.includes('invalid')||s.includes('not selected')||s.includes('failed')?'danger':s.includes('pending')||s.includes('verification')||s.includes('review')?'warn':'blue'}
function batchStatus(start){if(!start)return'—';const t=new Date();t.setHours(0,0,0,0);const d=new Date(start+'T00:00:00'),e=new Date(monthEnd(start)+'T23:59:59');return d>t?'Upcoming':new Date()<=e?'Active':'Completed'}
function studentStatus(s){return s.selection_status==='Selected'?'Selected':s.selection_status==='Not Selected'?'Not Selected':s.status}
function renderMetrics(){const active=batches.filter(b=>batchStatus(b.start_date)==='Active').length;const selected=students.filter(s=>s.selection_status==='Selected').length;const notSelected=students.filter(s=>s.selection_status==='Not Selected').length;const pay=students.filter(s=>s.payment_status==='Verified').length;const pending=students.filter(s=>['Pending','Under Verification'].includes(s.payment_status)).length;const assess=students.filter(s=>s.assessment_status!=='Complete').length;const completed=students.filter(s=>s.status==='Completed').length;document.getElementById('dashboardMetrics').innerHTML=[['Total Students',students.length,'Registered accounts'],['Active Batches',active,'Currently running'],['Selected',selected,'Selection completed'],['Not Selected',notSelected,'Selection result'],['Payment Verified',pay,'Verified payments'],['Payment Pending',pending,'Awaiting verification'],['Assessment Pending',assess,'Not yet complete'],['Completed Programs',completed,'Program completed']].map(x=>`<div class="metric-card"><small>${x[0]}</small><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}
