async function showNotificationHistory(userId){
  const student=students.find(x=>x.id===userId);
  const panel=document.getElementById('notificationHistoryPanel');
  const title=document.getElementById('notificationHistoryTitle');
  const body=document.getElementById('notificationHistoryBody');
  if(!panel||!body)return;
  title.textContent=`${student?.name||'Student'} — Notification History`;
  body.innerHTML='<div class="empty">Loading history…</div>';panel.style.display='block';
  const [{data:notes,error:ne},{data:reads,error:re}]=await Promise.all([adminSB.from('sgt_student_notes').select('id,category,message,created_at,created_by').eq('user_id',userId).order('created_at',{ascending:false}).limit(100),adminSB.from('sgt_student_notification_reads').select('notification_id,read_at').eq('user_id',userId)]);
  if(ne||re){body.innerHTML=`<div class="admin-note-empty">Unable to load notification history.</div>`;return}
  const readMap=new Map((reads||[]).map(r=>[String(r.notification_id),r.read_at]));
  body.innerHTML=(notes||[]).map(n=>`<div class="note-history-item"><div style="display:flex;justify-content:space-between;gap:10px"><strong>${ae(n.category||'General Update')}</strong><span class="status ${readMap.has(String(n.id))?'success':'blue'}">${readMap.has(String(n.id))?'Seen':'Sent'}</span></div><p>${ae(n.message||'')}</p><small>${adt(n.created_at)}${readMap.has(String(n.id))?' • Seen '+adt(readMap.get(String(n.id))):''}</small></div>`).join('')||'<div class="admin-note-empty">No notifications have been sent to this student.</div>';
}

async function sendAdminNotification(){
  if(!can(admin,'notifications.edit')&&!can(admin,'students.edit'))return toast('No permission.');
  const category=document.getElementById('notificationCategory')?.value||'General Update',msg=document.getElementById('notificationMessage')?.value.trim();
  if(!msg)return toast('Enter a notification message.'); if(!notificationSelection.size)return toast('Select at least one student.');
  const rows=[...notificationSelection].map(user_id=>({user_id,category,message:msg,created_by:admin.user.id}));
  const {error}=await adminSB.from('sgt_student_notes').insert(rows); if(error)return toast(error.message);
  await log('Sent notification','student',rows.map(x=>x.user_id).join(','),{category,count:rows.length});
  notificationSelection.clear(); document.getElementById('notificationMessage').value=''; await refreshNoteStatuses(); renderNotificationStudents(notificationCurrentBatch); toast('Notification sent to selected students.');
}
