function reassessmentQuestions(primary){return primary.map((q,i)=>{const prefix=['Compare or contrast the key idea in this question with a practical alternative: ','Suppose you had to explain this concept to a beginner. How would you approach it? ','What common mistake can occur with this concept, and how would you avoid it? ','Give a practical scenario where this concept would matter: ','How would you test or verify your understanding of this concept? ','If the first approach failed, what alternative would you consider? ','What trade-off should a developer consider when using this concept? ','How could this concept affect project quality or reliability? ','Describe a small real-world example involving this concept: ','What would you check first when solving a problem related to this concept? '][i];return prefix+q.replace(/^Explain |^What is |^Why is /,'').replace(/\.$/,'')+'?'});}
async function ensureDefaultAssessmentSets(){
  if(!admin||!can(admin,'assessment.edit')||!domains.length||!window.SGT_ASSESSMENT_BANK)return;
  const hasV2=questions.some(q=>q.question_set==='primary-v2');if(hasV2)return;
  try{await adminSB.from('sgt_assessment_questions').update({enabled:false}).in('question_set',['primary','reassessment']);}catch(e){console.warn('Old assessment question cleanup failed:',e.message)}
  const rows=[];
  for(const d of domains.filter(x=>x.enabled)){
    const bank=window.SGT_ASSESSMENT_BANK[d.name];if(!Array.isArray(bank)||bank.length<20)continue;
    bank.slice(0,20).forEach((item,i)=>rows.push({domain:d.name,question_set:'primary-v2',question_no:i+1,question:JSON.stringify({question:item.question,options:item.options}),enabled:true}));
    bank.slice(0,20).forEach((item,i)=>rows.push({domain:d.name,question_set:'reassessment-v2',question_no:i+1,question:JSON.stringify({question:`Second opportunity: ${item.question}`,options:item.options}),enabled:true}));
  }
  if(!rows.length)return;
  const {error}=await adminSB.from('sgt_assessment_questions').insert(rows);if(error){console.warn('Assessment v2 auto-publish failed:',error.message);return;}questions=[...questions,...rows];await log('Published 20-question domain assessment sets','assessment_question','',{version:'v2',count:rows.length});
}

async function seedDefaultAssessments(){if(!can(admin,'assessment.edit'))return toast('No permission.');await ensureDefaultAssessmentSets();const {error}=await adminSB.from('sgt_assessment_questions').update({enabled:true}).in('question_set',['primary-v2','reassessment-v2']);if(error)return toast(error.message);await log('Published default assessment questions','assessment_question','',{version:'v2'});await loadAll();toast('20-question domain assessment sets are published.')}
async function unpublishDefaultAssessments(){if(!can(admin,'assessment.edit'))return toast('No permission.');if(!confirm('Unpublish the default assessment questions? Students will not be able to start the assessment until the questions are published again.'))return;const {error}=await adminSB.from('sgt_assessment_questions').update({enabled:false}).in('question_set',['primary-v2','reassessment-v2']);if(error)return toast(error.message);await log('Unpublished default assessment questions','assessment_question','',{version:'v2'});await loadAll();toast('Assessment questions have been unpublished.')}
function assessmentQuestionsPublished(){return questions.some(q=>['primary-v2','reassessment-v2'].includes(q.question_set)&&q.enabled)}
function updateAssessmentPublishButton(){const b=document.getElementById('publishDefaultAssessments');if(!b)return;const published=assessmentQuestionsPublished();b.textContent=published?'Unpublish Questions':'Publish Default Questions';b.classList.toggle('danger',published);b.onclick=published?unpublishDefaultAssessments:seedDefaultAssessments}
function renderQuestions(){document.getElementById('questionRows').innerHTML=questions.filter(q=>q.enabled).map(q=>{let text=q.question;try{text=JSON.parse(q.question).question||text}catch(_){}return `<tr><td>${ae(q.domain)}</td><td>${ae(q.question_set)}</td><td>${ae(text)}</td><td>${q.question_no}</td><td><input type="checkbox" class="question-toggle" data-id="${q.id}" ${q.enabled?'checked':''}></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">No assessment questions published yet.</td></tr>';document.querySelectorAll('.question-toggle').forEach(c=>c.onchange=async()=>{if(!can(admin,'assessment.edit'))return toast('No permission.');const {error}=await adminSB.from('sgt_assessment_questions').update({enabled:c.checked}).eq('id',c.dataset.id);if(error)return toast(error.message);await log('Changed assessment question visibility','assessment_question',c.dataset.id,{enabled:c.checked});await loadAll()});updateAssessmentPublishButton()}

function assessmentResultRows(){
  const batch=document.getElementById('assessmentBatchFilter')?.value||assessmentCurrentBatch;
  const filter=document.getElementById('assessmentResultFilter')?.value||'';
  let rows=batch?(assessmentResultsByBatch.get(batch)||[]):[];
  // Once a student has been given a final selection decision, remove them from the
  // pending assessment-selection queue. Their record remains in Supabase.
  rows=rows.filter(r=>!['Selected','Not Selected'].includes(String(r.selectionStatus||'')));
  return rows.filter(r=>!filter||(filter==='15plus'&&r.submitted&&r.correct>=15)||(filter==='below15'&&r.submitted&&r.correct<15)||(filter==='Submitted'&&r.submitted));
}
function renderAssessmentResults(){
  const panel=document.getElementById('assessmentResultPanel');if(!panel)return;
  const batch=document.getElementById('assessmentBatchFilter')?.value||'';
  assessmentCurrentBatch=batch;
  const rows=assessmentResultRows();
  panel.style.display=batch?'block':'none';
  const title=document.getElementById('assessmentResultTitle');if(title)title.textContent=batch?`${ad(batch)} Batch — Assessment Results`:'Assessment Results';
  const summary=document.getElementById('assessmentResultSummary');if(summary)summary.textContent=batch?`${rows.length} students pending selection in this batch.`:'Select the assessment batch.';
  const tbody=document.getElementById('assessmentResultRows');
  if(!tbody)return;
  tbody.innerHTML=rows.map(r=>`<tr><td><input type="checkbox" class="assessment-result-check" data-id="${ae(r.userId)}" ${assessmentResultSelection.has(r.userId)?'checked':''}></td><td><strong>${ae(r.name)}</strong></td><td>${ae(r.studentId)}</td><td>20</td><td>${r.attempted}</td><td>${r.correct}</td><td><span class="status ${statusClass(r.displayStatus)}">${ae(r.displayStatus)}</span></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No students match this filter.</td></tr>';
  document.querySelectorAll('.assessment-result-check').forEach(c=>c.onchange=()=>{c.checked?assessmentResultSelection.add(c.dataset.id):assessmentResultSelection.delete(c.dataset.id);updateAssessmentSelectionUI()});
  updateAssessmentSelectionUI();
}
function updateAssessmentSelectionUI(){
  const rows=assessmentResultRows();
  const all=rows.length>0&&rows.every(r=>assessmentResultSelection.has(r.userId));
  const btn=document.getElementById('assessmentSelectAll');if(btn)btn.textContent=all?'↩ Undo Selection':'Select All';
  const count=document.getElementById('assessmentResultSelectedCount');if(count)count.textContent=`${assessmentResultSelection.size} selected`;
}
async function updateAssessmentSelectionStatus(status){
  if(!status)return;
  if(!['Selected','Not Selected'].includes(status))return;
  if(!can(admin,'assessment.edit'))return toast('No permission.');
  const ids=[...assessmentResultSelection];
  if(!ids.length)return toast('Select students first.');
  const selectedBefore=new Map(students.filter(s=>ids.includes(s.id)).map(s=>[s.id,s.selection_status]));
  const patch={selection_status:status,review_status:'Complete',updated_at:new Date().toISOString()};
  if(status==='Selected')patch.offer_issue_date=new Date().toISOString().slice(0,10);
  if(status==='Not Selected')patch.assessment_status='Not Started';
  const {error}=await adminSB.from('sgt_profiles').update(patch).in('id',ids);
  if(error)return toast(error.message);
  for(const id of ids){
    if(selectedBefore.get(id)===status)continue;
    const student=students.find(s=>s.id===id);
    const payment=String(student?.payment_status||'');
    let message='';
    if(status==='Selected'){
      message='Selection Confirmed\nCongratulations! You have been selected for the SoftGrowTech Internship Program. Your selection has been successfully confirmed.\n\nShare Your Achievement\nYour SoftGrowTech Offer Letter is an important milestone in your learning journey. Share your Offer Letter on LinkedIn or your social media to let your friends, classmates and professional network know about your next step.\n\nShare your journey. Inspire others. Keep learning, building and growing.';
    }else{
      message='Assessment Result — Your assessment has been reviewed and you have not been selected for this selection round. You may use the available re-assessment option if it is provided on your dashboard.';
    }
    const n=await adminSB.from('sgt_student_notes').insert({user_id:id,category:'Selection',message,created_by:admin.user.id});
    if(n.error)console.warn('Selection notification could not be created.',n.error.message);
    await triggerSelectionEmail(id);
  }
  await log('Updated assessment selection status','student',ids.join(','),{status,count:ids.length,batch:assessmentCurrentBatch});
  assessmentResultSelection.clear();
  toast(`${ids.length} student${ids.length===1?'':'s'} marked ${status}.`);
  await loadAll();
}

async function loadAssessmentResults(){
  assessmentAttempts=[];assessmentAnswers=[];
  const [ar,ans]=await Promise.all([
    adminSB.from('sgt_assessment_attempts').select('*').eq('status','Complete').order('submitted_at',{ascending:false}),
    adminSB.from('sgt_assessment_answers').select('*')
  ]);
  if(ar.error||ans.error){console.warn('Assessment result data unavailable:',ar.error?.message||ans.error?.message);assessmentResultsByBatch=new Map();renderAssessmentResults();return;}
  assessmentAttempts=ar.data||[];assessmentAnswers=ans.data||[];
  const answerByAttempt=new Map();
  for(const a of assessmentAnswers){if(!answerByAttempt.has(a.attempt_id))answerByAttempt.set(a.attempt_id,[]);answerByAttempt.get(a.attempt_id).push(a)}
  const qMap=new Map(questions.map(q=>[q.id,q]));
  const latest=new Map();
  for(const a of assessmentAttempts){
    const student=students.find(s=>s.student_id===a.student_id||s.id===a.user_id);
    if(!student||!student.batch_start)continue;
    const prior=latest.get(student.id);
    if(prior&&new Date(a.submitted_at||0).getTime()<=new Date(prior.submitted_at||0).getTime())continue;
    const answers=answerByAttempt.get(a.id)||[];let attempted=0,correct=0;
    for(const ans of answers){
      const val=String(ans.answer||'').trim();
      if(val)attempted++;
      const q=qMap.get(ans.question_id);if(!q||!val)continue;
      try{const parsed=JSON.parse(q.question);if(Array.isArray(parsed.options)&&val===String(parsed.options[0]))correct++}catch(_){ }
    }
    latest.set(student.id,{userId:student.id,name:student.name,studentId:student.student_id,batch:student.batch_start,attempted,correct,submitted:true,selectionStatus:student.selection_status||'',assessmentStatus:student.assessment_status,reviewStatus:student.review_status,displayStatus:student.selection_status&&student.selection_status!=='Pending'?student.selection_status:(student.review_status==='Under Review'?'Under Review':'Pending Selection'),submitted_at:a.submitted_at});
  }
  // Include every student in the batch, even when they have not submitted yet.
  for(const student of students){
    if(!student.batch_start||latest.has(student.id))continue;
    latest.set(student.id,{userId:student.id,name:student.name,studentId:student.student_id,batch:student.batch_start,attempted:0,correct:0,submitted:false,selectionStatus:student.selection_status||'',assessmentStatus:student.assessment_status,reviewStatus:student.review_status,displayStatus:student.selection_status&&student.selection_status!=='Pending'?student.selection_status:'Not Submitted',submitted_at:null});
  }
  const grouped=new Map();
  for(const r of latest.values()){if(!grouped.has(r.batch))grouped.set(r.batch,[]);grouped.get(r.batch).push(r)}
  for(const rows of grouped.values())rows.sort((a,b)=>b.correct-a.correct||a.name.localeCompare(b.name));
  assessmentResultsByBatch=grouped;
  const statsEl=document.getElementById('assessmentStats');
  if(statsEl){const submitted=assessmentAttempts.length;const completed=students.filter(s=>s.assessment_status==='Complete').length;const scores=[...latest.values()].filter(r=>r.submitted).map(r=>r.correct);const avg=scores.length?(scores.reduce((a,b)=>a+b,0)/scores.length).toFixed(1):'0';statsEl.innerHTML=[['Attempts',assessmentAttempts.length],['Completed',completed],['Submitted',submitted],['Average Score',`${avg}/20`]].map(x=>`<div class="metric-card"><small>${x[0]}</small><strong>${ae(x[1])}</strong></div>`).join('')}
  const filter=document.getElementById('assessmentBatchFilter');
  if(filter){
    const batchesWithStudents=[...new Set(students.filter(s=>s.batch_start).map(s=>s.batch_start))].sort((a,b)=>b.localeCompare(a));
    const current=assessmentCurrentBatch&&batchesWithStudents.includes(assessmentCurrentBatch)?assessmentCurrentBatch:(batchesWithStudents[0]||'');
    assessmentCurrentBatch=current;
    filter.innerHTML='<option value="">Select batch</option>'+batchesWithStudents.map(d=>`<option value="${ae(d)}">${ae(ad(d))} Batch</option>`).join('');
    filter.value=current;
  }
  renderAssessmentResults();
}
function paymentList(){const q=(document.getElementById('paymentSearch')?.value||'').trim().toLowerCase(),from=document.getElementById('payFrom')?.value||'',to=document.getElementById('payTo')?.value||'',batchFrom=document.getElementById('payBatchFrom')?.value||'',batchTo=document.getElementById('payBatchTo')?.value||'',dom=document.getElementById('payDomain')?.value||'',status=document.getElementById('payStatus')?.value||'',method=document.getElementById('payMethodFilter')?.value||'';const hasFilter=Boolean(q||from||to||batchFrom||batchTo||dom||status||method);if(!hasFilter)return[];return payments.filter(x=>{const st=students.find(s=>s.student_id===x.student_id);const hay=[x.student_id,st?.name,st?.email,st?.phone,x.transaction_id].join(' ').toLowerCase();const sd=(x.submitted_at||'').slice(0,10),bd=(st?.batch_start||'').slice(0,10);return(!q||hay.includes(q))&&(!from||sd>=from)&&(!to||sd<=to)&&(!batchFrom||bd>=batchFrom)&&(!batchTo||bd<=batchTo)&&(!dom||st?.domain===dom)&&(!status||x.status===status)&&(!method||x.method===method)})}
function updatePaymentSelectButton(){const btn=document.getElementById('selectAllPayments'),list=paymentFiltered;const all=list.length>0&&list.every(x=>paymentSelection.has(x.id));if(btn)btn.textContent=all?'↩ Undo Selection':'Select All';document.getElementById('paymentSelectedCount').textContent=`${paymentSelection.size} selected`}
function renderPayments(){paymentFiltered=paymentList();document.getElementById('paymentCount').textContent=`${paymentFiltered.length} payment records`;document.getElementById('paymentRows').innerHTML=paymentFiltered.map(x=>{const st=students.find(s=>s.student_id===x.student_id);return `<tr><td><input type="checkbox" class="pay-check" data-id="${x.id}" ${paymentSelection.has(x.id)?'checked':''}></td><td><strong>${ae(x.student_id)}</strong><br>${ae(st?.name||'')}</td><td>${ae(st?.email||'')}</td><td>${ae(st?.domain||'—')}</td><td>${ae(x.method)}</td><td>${ae(x.transaction_id||'—')}</td><td>${ae(x.amount||'—')}</td><td>${adt(x.submitted_at)}</td><td>${x.receipt_path?`<button class="portal-btn secondary receipt-view" data-path="${ae(x.receipt_path)}">Receipt</button>`:'—'}</td><td><span class="status ${statusClass(x.status)}">${ae(x.status)}</span><br><select class="payment-status" data-id="${x.id}">${['Under Verification','Verified','Invalid','Refund Pending','Refunded'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><input class="payment-note" data-id="${x.id}" value="${ae(x.admin_note||'')}" placeholder="Add a note for student"></td></tr>`}).join('')||'<tr><td colspan="11" class="empty">Use the filters above to find payment records.</td></tr>';document.querySelectorAll('.pay-check').forEach(c=>c.onchange=()=>{c.checked?paymentSelection.add(c.dataset.id):paymentSelection.delete(c.dataset.id);updatePaymentSelectButton()});document.querySelectorAll('.receipt-view').forEach(b=>b.onclick=async()=>{const {data,error}=await adminSB.storage.from('payment-receipts').createSignedUrl(b.dataset.path,600);if(error)toast(error.message);else window.open(data.signedUrl,'_blank','noopener')});document.querySelectorAll('.payment-status').forEach(el=>el.onchange=async()=>updateSinglePayment(el.dataset.id,{status:el.value}));document.querySelectorAll('.payment-note').forEach(el=>el.onchange=async()=>updateSinglePayment(el.dataset.id,{admin_note:el.value}));updatePaymentSelectButton();renderPaymentEditor()}
async function updateSinglePayment(id,patch){if(!can(admin,'payments.edit'))return toast('No permission.');const x=payments.find(p=>p.id===id),before={status:x?.status,admin_note:x?.admin_note};const {error}=await adminSB.rpc('sgt_admin_update_payment',{p_payment_id:id,p_status:Object.prototype.hasOwnProperty.call(patch,'status')?patch.status:null,p_admin_note:Object.prototype.hasOwnProperty.call(patch,'admin_note')?patch.admin_note:null});if(error)return toast(error.message);await log('Updated payment','payment',id,{before,after:patch});toast('Payment updated and student dashboard synced.');await loadAll()}
async function bulkPaymentStatus(status){if(!paymentSelection.size)return toast('Select payment records first.');if(!can(admin,'payments.edit'))return toast('No permission.');const ids=[...paymentSelection];for(const id of ids){const r=await adminSB.rpc('sgt_admin_update_payment',{p_payment_id:id,p_status:status,p_admin_note:null});if(r.error)return toast(r.error.message);const pay=payments.find(x=>x.id===id);if(status==='Invalid'){await adminSB.from('sgt_profiles').update({payment_rejected_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('student_id',pay?.student_id||'')}else if(['Under Verification','Verified'].includes(status)){await adminSB.from('sgt_profiles').update({payment_rejected_at:null,updated_at:new Date().toISOString()}).eq('student_id',pay?.student_id||'')}}await log('Bulk updated payment status','payment',ids.join(','),{status,count:ids.length});paymentSelection.clear();toast(`${ids.length} payment record(s) updated to ${status}.`);await loadAll()}
async function paymentQrSignedUrl(ref){
  const value=String(ref||'');
  if(!value.startsWith('storage://payment-qr-codes/')) return value;
  const path=value.replace('storage://payment-qr-codes/','');
  const session=await adminSB.auth.getSession(),token=session.data.session?.access_token;
  if(!token)return '';
  const r=await fetch(`${SGT_URL}/functions/v1/sgt-payment-qr`,{method:'POST',headers:{Authorization:`Bearer ${token}`,apikey:SGT_KEY,'Content-Type':'application/json'},body:JSON.stringify({action:'signed-url',path})});
  const result=await r.json().catch(()=>({}));
  return r.ok?String(result.signed_url||''):'';
}
async function uploadPaymentQr(method,file){
  const session=await adminSB.auth.getSession(),token=session.data.session?.access_token;
  if(!token)throw Error('Admin session expired. Please sign in again.');
  const fd=new FormData();fd.append('action','upload');fd.append('method',method);fd.append('file',file,file.name);
  const r=await fetch(`${SGT_URL}/functions/v1/sgt-payment-qr`,{method:'POST',headers:{Authorization:`Bearer ${token}`,apikey:SGT_KEY},body:fd});
  const result=await r.json().catch(()=>({}));
  if(!r.ok)throw Error(result.error||'Unable to upload QR code to private storage.');
  return `storage://payment-qr-codes/${result.path}`;
}
async function removePaymentQr(ref){
  const value=String(ref||'');if(!value.startsWith('storage://payment-qr-codes/'))return;
  const session=await adminSB.auth.getSession(),token=session.data.session?.access_token;if(!token)throw Error('Admin session expired. Please sign in again.');
  const path=value.replace('storage://payment-qr-codes/','');
  const r=await fetch(`${SGT_URL}/functions/v1/sgt-payment-qr`,{method:'POST',headers:{Authorization:`Bearer ${token}`,apikey:SGT_KEY,'Content-Type':'application/json'},body:JSON.stringify({action:'remove',path})});
  const result=await r.json().catch(()=>({}));if(!r.ok)throw Error(result.error||'Unable to remove QR code.');
}
