    const file=document.getElementById(`qrFile_${g[0]}`),previewWrap=document.getElementById(`qrPreviewWrap_${g[0]}`),remove=document.querySelector(`.remove-qr-btn[data-method="${g[0]}"]`);
    file?.addEventListener('change',()=>{const f=file.files?.[0];if(!f)return;if(f.size>2*1024*1024){toast('QR image must be 2 MB or smaller.');file.value='';return}const url=URL.createObjectURL(f);if(previewWrap)previewWrap.innerHTML=`<img src="${url}" alt="${ae(g[1])} new QR preview" style="width:120px;height:120px;object-fit:contain;background:#fff;border-radius:10px;padding:6px">`;if(remove)remove.disabled=false});
    remove?.addEventListener('click',async()=>{if(!document.getElementById(`qr_${g[0]}`).value)return;if(!confirm(`Remove the current ${g[1]} QR code?`))return;const btn=remove;btn.disabled=true;btn.textContent='Removing…';try{await removePaymentQr(document.getElementById(`qr_${g[0]}`).value);document.getElementById(`qr_${g[0]}`).value='';document.getElementById(`qrFile_${g[0]}`).value='';if(previewWrap)previewWrap.innerHTML='<div style="width:120px;height:120px;display:grid;place-items:center;border:1px dashed #cbd5e1;border-radius:10px;color:#64748b;font-size:12px;text-align:center">No QR uploaded</div>';btn.textContent='QR Removed';}catch(err){toast(err.message);btn.disabled=false;btn.textContent='Remove QR Code'}});
