async function renderTeam(){const box=document.getElementById('teamRows');if(!box)return;const q=(document.getElementById('teamSearch')?.value||'').trim().toLowerCase();const query=admin.role==='founder'?adminSB.from('sgt_admin_members').select('*').order('created_at',{ascending:false}):adminSB.from('sgt_admin_members').select('*').eq('user_id',admin.user.id).eq('active',true);const {data,error}=await query;if(error)return toast(error.message);const rows=(data||[]).filter(x=>!q||[x.email,x.role,(x.permissions||[]).join(' ')].join(' ').toLowerCase().includes(q));box.innerHTML=rows.map(x=>`<tr><td><strong>${ae(x.email)}</strong></td><td>${ae(x.role||'team_admin')}</td><td>${x.active?`<span class="status success">Active</span>`:`<button type="button" class="status danger team-permanent-remove" data-id="${ae(x.id)}" title="Permanently remove this team member">Removed</button>`}</td><td>${ad(x.created_at)}</td><td>${ae((x.permissions||[]).join(', ')||'No permissions')}</td><td>${admin.role==='founder'?`<button class="portal-btn secondary team-edit" data-id="${x.id}">Edit Permissions</button> <button class="portal-btn secondary team-password" data-id="${x.id}" data-email="${ae(x.email)}">Set Password</button> ${x.active?`<button class="portal-btn danger team-remove" data-id="${x.id}">Remove Access</button>`:`<button class="portal-btn primary team-restore" data-id="${x.id}">Restore</button> <button class="portal-btn danger team-permanent-remove" data-id="${x.id}">Remove Permanently</button>`}`:'<span class="pill">Your Access</span>'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No team members found.</td></tr>';document.querySelectorAll('.team-edit').forEach(b=>b.onclick=()=>editTeamMember(b.dataset.id));document.querySelectorAll('.team-password').forEach(b=>b.onclick=()=>setTeamPassword(b.dataset.id,b.dataset.email));document.querySelectorAll('.team-remove').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this team member access?'))return;const {error}=await adminSB.rpc('sgt_set_admin_member_active',{p_member_id:b.dataset.id,p_active:false});if(error)return toast(error.message);await log('Removed team admin access','admin_member',b.dataset.id);toast('Team member access removed. Click Removed to permanently delete this team member.');renderTeam()});document.querySelectorAll('.team-restore').forEach(b=>b.onclick=async()=>{if(admin.role!=='founder')return toast('Founder access only.');if(!confirm('Restore this team member access?'))return;const {error}=await adminSB.rpc('sgt_set_admin_member_active',{p_member_id:b.dataset.id,p_active:true});if(error)return toast(error.message);await log('Restored team admin access','admin_member',b.dataset.id);toast('Team member access restored.');renderTeam()});document.querySelectorAll('.team-permanent-remove').forEach(b=>b.onclick=async()=>{if(admin.role!=='founder')return toast('Founder access only.');if(!confirm('Permanently remove this team member? Their Management Console access will be revoked and their team-access record will be deleted. Activity Log records will be preserved.'))return;const session=await adminSB.auth.getSession(),token=session.data.session?.access_token;if(!token)return toast('Admin session expired. Please sign in again.');const r=await fetch(`${SGT_URL}/functions/v1/sgt-delete-team-member`,{method:'POST',headers:{Authorization:`Bearer ${token}`,apikey:SGT_KEY,'Content-Type':'application/json'},body:JSON.stringify({member_id:b.dataset.id})});const result=await r.json().catch(()=>({}));if(!r.ok)return toast(result.error||'Unable to permanently remove team member.');await log('Permanently removed team admin','admin_member',b.dataset.id,{activity_log_preserved:true});toast('Team member permanently removed.');renderTeam()})}
async function setTeamPassword(id,email){
  if(admin.role!=='founder')return toast('Founder access only.');
  const password=prompt(`Set a new password for ${email} (minimum 8 characters):`);
  if(password===null)return;
  if(password.length<8)return toast('Use a password with at least 8 characters.');
  const confirmPassword=prompt('Confirm the new password:');
  if(password!==confirmPassword)return toast('Passwords do not match.');
  const session=await adminSB.auth.getSession(),token=session.data.session?.access_token;
  if(!token)return toast('Admin session expired. Please sign in again.');
  const r=await fetch(`${SGT_URL}/functions/v1/sgt-set-team-password`,{method:'POST',headers:{Authorization:`Bearer ${token}`,apikey:SGT_KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password})});
  const result=await r.json().catch(()=>({}));
  if(!r.ok)return toast(result.error||'Unable to update the team member password.');
  await log('Changed team admin password','admin_member',id,{email,password_managed_by:'Founder'});
  toast('Team member password updated.'); 
}
async function editTeamMember(id){
  if(admin.role!=='founder')return toast('Founder access only.');
  const {data,error}=await adminSB.from('sgt_admin_members').select('*').eq('id',id).maybeSingle();
  if(error)return toast(error.message);if(!data)return;
  const groups={
    Students:['view','add','edit','delete'],
    Batches:['view','add','edit','delete'],
    Domains:['view','add','edit','delete'],
    Tasks:['view','add','edit','delete'],
    Assessment:['view','add','edit','delete'],
    Payments:['view','verify','edit'],
    Documents:['view','edit'],
    Communication:['view','edit'],
    Notifications:['view','edit'],
    Services:['view','edit'],
    Support:['view','edit'],
    Enquiries:['view','edit'],
    Settings:['view','edit'],
    Ambassador:['view','edit']
  };
  const body=document.getElementById('permissionModalBody');if(!body)return;
  body.innerHTML=Object.entries(groups).map(([label,actions])=>{const section=label.toLowerCase();return `<div class="permission-group"><strong>${label}</strong>${actions.map(action=>{const value=`${section}.${action}`;return `<label><input type="checkbox" class="permission-choice" value="${ae(value)}" ${(data.permissions||[]).includes(value)?'checked':''}> ${action.charAt(0).toUpperCase()+action.slice(1)}</label>`}).join('')}</div>`}).join('');
  const modal=document.getElementById('permissionModal');modal.hidden=false;modal.classList.add('open');
  const close=()=>{modal.hidden=true;modal.classList.remove('open')};
  document.getElementById('permissionCancel').onclick=close;document.getElementById('permissionCancelTop').onclick=close;
  document.getElementById('permissionSave').onclick=async()=>{
    const perms=[...body.querySelectorAll('.permission-choice:checked')].map(x=>x.value);
    const b=document.getElementById('permissionSave');b.disabled=true;b.textContent='Saving…';
    const {error:e}=await adminSB.rpc('sgt_update_admin_member_permissions',{p_member_id:id,p_permissions:perms});
    if(e){toast(e.message);b.disabled=false;b.textContent='Save Permissions';return}
    await log('Updated team admin permissions','admin_member',id,{email:data.email,permissions:perms});toast('Permissions updated.');b.disabled=false;b.textContent='Save Permissions';close();renderTeam();
  };
}

function ambassadorTier(successful){const n=Number(successful||0);if(n>=30)return 5;if(n>=20)return 4;if(n>=15)return 3;if(n>=10)return 2;if(n>=5)return 1;return 0}
function ambassadorTierLabel(successful){const t=ambassadorTier(successful);return t?`Tier ${t}`:'Not Unlocked'}
function rewardStatusForStudent(studentId){return ambassadorRewards.filter(r=>r.student_id===studentId).map(r=>r.status).filter(Boolean)}
function successfulCountFor(refId){return ambassadorReferrals.filter(r=>r.referrer_student_id===refId&&r.status==='Successful').length}
function pointsForAmb(ambId){return ambassadorPoints.filter(p=>p.ambassador_id===ambId).reduce((a,b)=>a+Number(b.points||0),0)}
async function loadAmbassadorData(){const [a,r,pl,rew]=await Promise.all([adminSB.from('sgt_ambassador_profiles').select('*').order('created_at',{ascending:false}),adminSB.from('sgt_ambassador_referrals').select('*').order('created_at',{ascending:false}),adminSB.from('sgt_ambassador_point_ledger').select('*').order('created_at',{ascending:false}),adminSB.from('sgt_ambassador_rewards').select('*').order('created_at',{ascending:false})]);for(const x of [a,r,pl,rew])if(x.error)throw x.error;ambassadorProfiles=a.data||[];ambassadorReferrals=r.data||[];ambassadorPoints=pl.data||[];ambassadorRewards=rew.data||[]}
function renderAmbassadorMetrics(){const totalAmb=ambassadorProfiles.length,active=ambassadorProfiles.filter(x=>x.is_active).length,totalRef=ambassadorReferrals.length,successful=ambassadorReferrals.filter(x=>x.status==='Successful').length,unlocked=ambassadorRewards.length,paid=ambassadorRewards.filter(x=>x.status==='Paid').length,pending=ambassadorRewards.filter(x=>x.status==='Pending'||x.status==='Approved').length;document.getElementById('ambassadorMetrics').innerHTML=[['Total Ambassadors',totalAmb],['Active Ambassadors',active],['Total Referrals',totalRef],['Successful Referrals',successful],['Total Rewards Unlocked',unlocked],['Rewards Paid',paid],['Pending Rewards',pending]].map(([a,b])=>`<div class="metric-card"><small>${a}</small><strong>${b}</strong></div>`).join('')}
function renderAmbassadors(){const q=(document.getElementById('ambassadorSearch')?.value||'').trim().toLowerCase(),tier=document.getElementById('ambassadorTierFilter')?.value||'',sf=document.getElementById('ambassadorSuccessFilter')?.value||'',rf=document.getElementById('ambassadorRewardFilter')?.value||'';let rows=ambassadorProfiles.map(a=>{const s=students.find(x=>x.id===a.student_id)||{};const successful=successfulCountFor(a.student_id),points=pointsForAmb(a.id),rewards=rewardStatusForStudent(a.student_id),tierNo=ambassadorTier(successful);return {a,s,successful,points,rewards,tierNo}});rows=rows.filter(x=>{const text=[x.s.name,x.s.student_id,x.a.referral_code].join(' ').toLowerCase();if(q&&!text.includes(q))return false;if(tier&&String(x.tierNo)!==tier)return false;if(sf){if(sf==='0'&&x.successful!==0)return false;if(sf==='1-4'&&(x.successful<1||x.successful>4))return false;if(sf==='5-9'&&(x.successful<5||x.successful>9))return false;if(sf==='10-14'&&(x.successful<10||x.successful>14))return false;if(sf==='15-19'&&(x.successful<15||x.successful>19))return false;if(sf==='20-29'&&(x.successful<20||x.successful>29))return false;if(sf==='30+'&&x.successful<30)return false}if(rf){if(rf==='none'&&x.rewards.length)return false;if(rf==='unlocked'&&!x.rewards.includes('Unlocked'))return false;if(rf==='pending'&&!x.rewards.includes('Pending'))return false;if(rf==='approved'&&!x.rewards.includes('Approved'))return false;if(rf==='paid'&&!x.rewards.includes('Paid'))return false}return true});document.getElementById('ambassadorRows').innerHTML=rows.map(x=>`<tr><td><strong>${ae(x.s.name||'—')}</strong></td><td>${ae(x.s.student_id||'—')}</td><td>${ambassadorReferrals.filter(r=>r.referrer_student_id===x.student_id).length}</td><td>${x.successful}</td><td>${ambassadorTierLabel(x.successful)}</td><td>${x.points.toLocaleString('en-IN')}</td><td>${x.rewards.length?x.rewards.map(r=>Number(r.reward_amount||0)?`₹${Number(r.reward_amount).toLocaleString('en-IN')}`:r.reward_name).join(', '):'—'}</td><td><button class="portal-btn secondary ambassador-open" data-id="${ae(x.a.id)}">Open</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No Ambassadors match the selected filters.</td></tr>';document.querySelectorAll('.ambassador-open').forEach(b=>b.onclick=()=>openAmbassadorProfile(b.dataset.id))}
function renderReferralActivity(){const q=(document.getElementById('referralActivitySearch')?.value||'').trim().toLowerCase(),status=document.getElementById('referralActivityStatus')?.value||'';const rows=ambassadorReferrals.filter(r=>{const a=ambassadorProfiles.find(x=>x.id===r.ambassador_id),s=students.find(x=>x.id===r.referred_student_id),ref=students.find(x=>x.id===r.referrer_student_id);const text=[s?.name,s?.student_id,ref?.name,ref?.student_id,a?.referral_code].join(' ').toLowerCase();return (!q||text.includes(q))&&(!status||r.status===status)});document.getElementById('referralActivityRows').innerHTML=rows.map(r=>{const s=students.find(x=>x.id===r.referred_student_id)||{},ref=students.find(x=>x.id===r.referrer_student_id)||{};return `<tr><td><strong>${ae(s.name||'—')}</strong><br><small>${ae(s.student_id||'')}</small></td><td>${ae(ref.name||'—')}<br><small>${ae(ref.student_id||'')}</small></td><td>${ae(s.payment_status||'—')}</td><td>${ae(s.selection_status||'—')}</td><td><span class="status ${statusClass(r.status)}">${ae(r.status)}</span></td><td>+${Number(r.points_awarded||0)}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No referral activity matches your search.</td></tr>'}
function renderAmbassadorRewards(){const q=(document.getElementById('ambassadorRewardSearch')?.value||'').trim().toLowerCase(),status=document.getElementById('ambassadorRewardStatus')?.value||'';const rows=ambassadorRewards.filter(r=>{const s=students.find(x=>x.id===r.student_id)||{};return (!q||[s.name,s.student_id].join(' ').toLowerCase().includes(q))&&(!status||r.status===status)});document.getElementById('ambassadorRewardRows').innerHTML=rows.map(r=>{const s=students.find(x=>x.id===r.student_id)||{};const canPay=['Pending','Approved'].includes(r.status);return `<tr><td><strong>${ae(s.name||'—')}</strong><br><small>${ae(s.student_id||'')}</small></td><td>Tier ${r.tier}</td><td>${ae(r.reward_name)}${Number(r.reward_amount||0)?` — ₹${Number(r.reward_amount).toLocaleString('en-IN')}`:''}</td><td>${Number(r.points_snapshot||0).toLocaleString('en-IN')}</td><td><span class="status ${statusClass(r.status)}">${ae(r.status)}</span></td><td>${ae(r.payment_reference||'—')}</td><td>${ad(r.paid_at)}</td><td>${canPay?`<button class="portal-btn secondary reward-approve" data-id="${ae(r.id)}">${r.status==='Pending'?'Approve':'Mark Paid'}</button>`:'—'}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No rewards match your search.</td></tr>';document.querySelectorAll('.reward-approve').forEach(b=>b.onclick=async()=>{const r=ambassadorRewards.find(x=>x.id===b.dataset.id);if(!r)return;if(r.status==='Pending'){const {error}=await adminSB.from('sgt_ambassador_rewards').update({status:'Approved'}).eq('id',r.id);if(error)return toast(error.message);await log('Approved Ambassador reward','ambassador_reward',r.id,{student_id:r.student_id,tier:r.tier});toast('Reward approved.');}else{const ref=prompt('Transaction / Payment Reference:',r.payment_reference||'');if(ref===null)return;const {error}=await adminSB.from('sgt_ambassador_rewards').update({status:'Paid',payment_reference:ref.trim()||null,paid_at:new Date().toISOString()}).eq('id',r.id);if(error)return toast(error.message);await log('Marked Ambassador reward paid','ambassador_reward',r.id,{student_id:r.student_id,tier:r.tier,payment_reference:ref.trim()||null});toast('Reward marked paid.');}await loadAmbassadorData();renderAmbassador()})}
async function openAmbassadorProfile(ambId){const a=ambassadorProfiles.find(x=>x.id===ambId);if(!a)return;const s=students.find(x=>x.id===a.student_id)||{};const refs=ambassadorReferrals.filter(x=>x.referrer_student_id===a.student_id);const rewards=ambassadorRewards.filter(x=>x.student_id===a.student_id);const points=pointsForAmb(a.id),successful=refs.filter(x=>x.status==='Successful').length;const tiers=[1,2,3,4,5].map(t=>({t,done:successful>=[5,10,15,20,30][t-1]}));document.getElementById('studentDrawerBody').innerHTML=`<div class="admin-card" style="margin-top:18px"><h3>${ae(s.name||'Ambassador')} — Ambassador Profile</h3><div class="portal-meta"><div class="meta-box"><small>Student ID</small><strong>${ae(s.student_id||'—')}</strong></div><div class="meta-box"><small>Referral Code</small><strong>${ae(a.referral_code)}</strong></div><div class="meta-box"><small>Current Tier</small><strong>${ae(ambassadorTierLabel(successful))}</strong></div><div class="meta-box"><small>Total Successful Referrals</small><strong>${successful}</strong></div><div class="meta-box"><small>Reward Points</small><strong>${points.toLocaleString('en-IN')}</strong></div></div></div><div class="admin-card"><h3>Tier Progress</h3>${tiers.map(x=>`<div class="help-note" style="margin-top:8px">Tier ${x.t}: ${x.done?'✓ Completed':'Not Completed'} <span style="float:right">${[5,10,15,20,30][x.t-1]} Total Successful Referrals</span></div>`).join('')}</div><div class="admin-card"><h3>Rewards</h3>${rewards.map(r=>`<div class="help-note" style="margin-top:8px"><strong>Tier ${r.tier} — ${ae(r.reward_name)}</strong><br>Status: ${ae(r.status)}${r.payment_reference?`<br>Reference: ${ae(r.payment_reference)}`:''}</div>`).join('')||'<div class="empty">No milestone rewards yet.</div>'}</div><div class="admin-card"><h3>Referral History</h3><div class="table-scroll"><table class="admin-table"><thead><tr><th>Referred Student</th><th>Registration</th><th>Payment</th><th>Selection</th><th>Referral Status</th><th>Points</th></tr></thead><tbody>${refs.map(r=>{const rs=students.find(x=>x.id===r.referred_student_id)||{};return `<tr><td>${ae(rs.name||'—')}<br><small>${ae(rs.student_id||'')}</small></td><td>✓</td><td>${ae(rs.payment_status||'—')}</td><td>${ae(rs.selection_status||'—')}</td><td>${ae(r.status)}</td><td>+${Number(r.points_awarded||0)}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No referral history.</td></tr>'}</tbody></table></div></div>`;document.getElementById('studentDrawer').classList.add('open')}
