async function renderAudit(){if(admin.role!=='founder'){document.getElementById('auditRows').innerHTML='<tr><td colspan="4" class="empty">Founder access only.</td></tr>';return}const q=(document.getElementById('auditSearch')?.value||'').trim().toLowerCase();const {data,error}=await adminSB.from('sgt_admin_audit').select('*').order('created_at',{ascending:false}).limit(1000);if(error)return toast(error.message);const mr=await adminSB.from('sgt_admin_members').select('user_id,email,role');const members=mr.data||[];const names=new Map(members.map(m=>[m.user_id,m.email]));const teamBox=document.getElementById('auditTeamList');if(teamBox)teamBox.innerHTML='<span class="pill">Filter by team:</span>'+members.map(m=>`<button type="button" class="portal-btn secondary audit-team-chip" data-email="${ae(m.email)}">${ae(m.email)}</button>`).join('');teamBox?.querySelectorAll('.audit-team-chip').forEach(b=>b.onclick=()=>{const inp=document.getElementById('auditSearch');if(inp){inp.value=b.dataset.email;renderAudit()}});const rows=(data||[]).filter(x=>!q||[x.action,x.target_type,x.target_id,JSON.stringify(x.details||{}),names.get(x.admin_user)||'Founder'].join(' ').toLowerCase().includes(q));document.getElementById('auditRows').innerHTML=rows.map(x=>`<tr><td>${adt(x.created_at)}</td><td><strong>${ae(names.get(x.admin_user)||'Founder')}</strong><br>${ae(x.action)}</td><td>${ae(x.target_type||'')} ${ae(x.target_id||'')}</td><td><pre style="white-space:pre-wrap;margin:0;font:inherit;color:#475569">${ae(JSON.stringify(x.details||{},null,2))}</pre></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No activity matches your search.</td></tr>'}
